pluginDev.contract:
from pathlib import Path
from autolingua2.plugins.contracts import (
    FileAdapter, GameProfile, ImportedTranslation,
    FilterRule, TranslationExporter, ExportFile,
)

class FileAdapter:
    id: str
    name: str
    suffixes: set[str]
    default_filter_rules: list[FilterRule]
    supported_games: list[GameProfile]

    def can_load(self, path: Path) -> bool: ...
    def load(self, path: Path) -> ImportedTranslation: ...
    def detect_source_language(self, path: Path) -> str | None: ...
    def filter_source_files(
        self, paths: list[Path], source_slot: str
    ) -> list[Path]: ...

class TranslationExporter:
    id: str
    name: str
    exchange: bool

    def plan(
        self, workspaces: list[ImportedTranslation],
        settings: dict[str, object]
    ) -> list[ExportFile]: ...

